import hashlib,json,tempfile
from pathlib import Path
checks=[]
def check(i,expected,actual,scope):
    assert actual==expected,(i,expected,actual)
    checks.append({"check_id":i,"expected":expected,"actual":actual,"status":"PASS","scope":scope})
check("B-PR-APPLICABILITY",[True,"v2.0-cyanoptera","59ae0c6fb3f29369cfd0df124c76e9232181ef86"],data["pr_fields"],"Exact public merged PR fields; not stable release behavior")
marker="result.last_position.buffer_pos > previous_buffer_handle->actual_size"
check("B-MERGE-EXACT-GUARD",True,marker in data["merge_function"],"Exact ProcessOverBufferValue source text")
check("B-RELEASE-EXACT-GUARD-ABSENT",False,marker in data["release_function"],"Exact guard absence; equivalent fix/runtime not assessed")
check("B-RELEASE-TEST-404",404,data["release_test_http_status"],"Exact regression path only")
assert "repeat('p', 23)" in data["test"] and "repeat('x', 19)" in data["test"] and "generate_series(0, 59)" in data["test"]
header=b'p'*23+b'\r\r\n'
rows=[f'{i:02d},'.encode()+b'x'*19+b'\r\r\n' for i in range(60)]
fixture=header+b''.join(rows)
first_cr=len(header)+sum(len(r) for r in rows[:39])+rows[39].index(b'\r')
check("B-W01-INDEPENDENT-FIXTURE-GEOMETRY",[26,25,1526,1023,b'\r\r\n'.hex()],[len(header),len(rows[39]),len(fixture),first_cr,fixture[1023:1026].hex()],"Actual evaluator-generated bytes from upstream literals; no DuckDB execution")
check("B-W01-NEGATIVE-CONTROL",1022,first_cr-1,"One shorter header moves terminator; arithmetic is not release behavior")
with tempfile.TemporaryDirectory() as td:
    p=Path(td)/'input.csv'; old=b'id,value\n1,10\n'; changed=b'id,value\n1,99\n'
    p.write_bytes(old); before=hashlib.sha256(p.read_bytes()).hexdigest()
    p.write_bytes(changed); actual_read=p.read_bytes(); result_value=int(actual_read.splitlines()[1].split(b',')[1])
    p.write_bytes(old); after=hashlib.sha256(p.read_bytes()).hexdigest()
    check("A-IDENTITY-COUNTEREXAMPLE-HASHES",True,before==after,"Filesystem interleaving: pre/post hashes accept original bytes")
    check("A-IDENTITY-COUNTEREXAMPLE-OUTPUT",99,result_value,"Worker observed transient changed bytes; original manifest value is 10")
    check("A-IDENTITY-COUNTEREXAMPLE-MISASSOCIATION",True,hashlib.sha256(actual_read).hexdigest()!=before,"Refutes stated cannot-associate-wrong-output guarantee for mutable original references")
    snapshot=bytes(old);p.write_bytes(changed)
    check("A-IDENTITY-SNAPSHOT-CONTROL",10,int(snapshot.splitlines()[1].split(b',')[1]),"An actually immutable byte snapshot avoids this particular interleaving; no product fix tested")
print(json.dumps({"schema":"er9.evaluator-typed-checks.v1","checks":checks,"source_quality_implication":{"A":"Consequential provenance guarantee counterexample; FAIL_SCREEN is limited to this claim","B":"Catalog claim subset supported; designated proposal absent, never promoted"},"limitations":["No DuckDB binary, kernel, upstream regression or complete product executed","Filesystem interleaving is deterministic witness, not a claimed production exploit"]},sort_keys=True))
